 * Duplicates are allowed if there are more than 2 waypoints, but the first and last waypoint must be different.
 */
function validateWaypoints(waypoints: WaypointCollection): boolean {
    const validatedWaypoints = getValidWaypoints(waypoints);
    if (Object.keys(validatedWaypoints).length < 2) {
        return false;
    }
    const startWaypoint = Object.values(validatedWaypoints)[0];
    const endWaypoint = Object.values(validatedWaypoints).slice(-1)[0];

    if (lodashIsEqual(startWaypoint, endWaypoint)) {
        return false;
    }
    return true;
}

